<?php require_once __DIR__ . '/includes/functions.php'; $order=db_fetch('SELECT o.*,pc.case_code,p.full_name FROM orders o JOIN patient_cases pc ON pc.id=o.case_id JOIN patients p ON p.id=o.patient_id WHERE o.id=?',[(int)($_GET['order']??0)]); public_header('Order Success'); ?><section class="py-5"><div class="container"><div class="card soft-card"><div class="card-body text-center p-5"><?php if($order): ?><h1 class="text-teal">Order requested</h1><p>Your order ID is <strong><?= e($order['order_code']) ?></strong> for case <strong><?= e($order['case_code']) ?></strong>.</p><p>Status: Pending Specialist Verification. Our team will contact you by WhatsApp/phone after approval.</p><a href="track-case.php" class="btn btn-teal">Track Case</a><?php else: ?><?= empty_state('Order not found.') ?><?php endif; ?></div></div></div></section><?php public_footer(); ?>
